$ErrorActionPreference='Stop'
$root=[IO.Path]::GetFullPath($PSScriptRoot);$lock=Get-Content (Join-Path $root 'open-source.lock.json') -Raw|ConvertFrom-Json
$ida='C:\Users\Mazum\Downloads\ida93sp1\IDA\idat.exe';$ghidra='C:\Users\Mazum\Desktop\ghidra_12.1.2_PUBLIC_20260605\ghidra_12.1.2_PUBLIC\support\analyzeHeadless.bat';$tools=Join-Path $root 'tools';$run=Join-Path $root 'runs\competitors';New-Item -ItemType Directory -Force $run|Out-Null
foreach($target in $lock.targets){$binary=Join-Path $root $target.binary;$focus=$target.focus -join ',';$env:HEXCORE_COMPARE_OUTPUT=Join-Path $run "$($target.id)-ida.json";$env:HEXCORE_COMPARE_FOCUS=$focus;$idb=Join-Path $run "$($target.id).i64";& $ida -A "-S$tools\ida_metrics.py" "-o$idb" $binary | Out-Null;if ($LASTEXITCODE -ne 0) {throw "IDA failed for $($target.id)"};$project=Join-Path $run 'ghidra-projects';New-Item -ItemType Directory -Force $project|Out-Null;& $ghidra $project "project-$($target.id)" -import $binary -scriptPath $tools -postScript HexcoreMetrics.java (Join-Path $run "$($target.id)-ghidra.json") $focus -deleteProject | Out-Null;if ($LASTEXITCODE -ne 0) {throw "Ghidra failed for $($target.id)"}}
Remove-Item Env:HEXCORE_COMPARE_OUTPUT,Env:HEXCORE_COMPARE_FOCUS -ErrorAction SilentlyContinue
$rows=@();foreach($target in $lock.targets){$idaJson=Get-Content (Join-Path $run "$($target.id)-ida.json") -Raw|ConvertFrom-Json;$ghidraJson=Get-Content (Join-Path $run "$($target.id)-ghidra.json") -Raw|ConvertFrom-Json;if ($idaJson.binarySha256 -ne $ghidraJson.binarySha256) {throw 'Competitor binary hash mismatch'};$rows+=[ordered]@{id=$target.id;binarySha256=$idaJson.binarySha256;ida=$idaJson;ghidra=$ghidraJson}}
$result=[ordered]@{schemaVersion=1;idaExecutableSha256=(Get-FileHash $ida -Algorithm SHA256).Hash.ToLowerInvariant();ghidraLauncherSha256=(Get-FileHash $ghidra -Algorithm SHA256).Hash.ToLowerInvariant();targets=$rows};$result|ConvertTo-Json -Depth 12|Set-Content (Join-Path $run 'competitor-baselines.json') -Encoding utf8;Write-Output 'IDA/Ghidra baselines complete'
